"""Статья «Бассейны» для раздела «Справочники → Бассейны».

Исходный текст подготовлен ООО «Тэга плюс», здесь он проверен, исправлен и дополнен. Рекламный блок убран.
Что исправлено:
 - убраны данные рынка (объёмы и рост рынка оборудования), таблица брендов и «мировой топ»: проверить актуальность и наличие в Беларуси не удалось;
 - «тепловой насос в 5–7 раз дешевле ТЭНа» заменено: COP 5–7 это паспортные значения при тёплом воздухе, среднесезонный COP в нашем климате ниже (ориентир 4–5, в калькуляторе 4,5);
 - «70 % потерь это испарение» дано как оценка по литературе («до 70 %»), а не как норма;
 - «павильон продлевает сезон с 3 до 5–6 месяцев» помечено как практика;
 - отступ 3 м от границы: по публикациям об Изменении № 4 к СН 3.01.03-2020 (с 01.12.2026) 3 м установлены для жилого дома, 2 м для хозяйственных построек;
   для бассейна отдельная норма не подтверждена, поэтому формулировка «3 м для построек и сооружений» заменена на «уточните в отделе архитектуры»;
 - Указ № 202 от 13.06.2022 действительно даёт упрощённый порядок для одноквартирных домов и нежилых капитальных построек 5-го класса сложности, но бассейн в его тексте не назван,
   поэтому «бассейн оформляется по упрощённому порядку» заменено на «уточните порядок оформления»;
 - «сброс промывочных вод за границу запрещён по Водному кодексу с 01.01.2027» заменено на общее требование: нельзя сбрасывать на соседний участок и на рельеф, отводить в свой дренаж или канализацию;
 - исправлена невнятная фраза про приямок и дренаж (нужен дренаж по периметру при высоком уровне грунтовых вод, пустую чашу выдавливает);
 - таблица энергии пересчитана по той же модели, что и калькулятор: «ЭлектроТЭН без покрытия 16 500 кВт·ч» и «котёл 5 400 кВт·ч» из PDF не воспроизводятся и убраны;
 - диаметры труб из PDF дополнены проверкой по скоростям воды, для биопула нужны трубы большого диаметра;
 - цифры, которые не нормы, а практика (оборот, нагрузка на фильтр, УФ, электролиз, покрытия, вентиляция, испытания), оставлены и помечены.
Источники: СН 3.01.03-2020 с Изменением № 4 (по публикациям); Указ Президента № 202 от 13.06.2022; паспорта оборудования; техническая литература по бассейнам.
"""
from art_heat import _sec, _ul, _tbl, _note, _box, _p, _errs, _kpis
from art_pool_figs import f_circuits, f_circuit, f_energy


def article():
    s = ""
    s += _kpis([("4–6 ч", "полный оборот воды химического бассейна, ориентир практики"), ("до 70 %", "потерь тепла открытой воды по оценкам уходит с испарением"),
                ("COP 4–5", "среднесезонный тепловой насос в нашем климате, ориентир практики"), ("pH 7,2–7,6", "рабочий коридор: при 8,0 хлор почти не дезинфицирует")])
    s += f_circuits()
    s += _box("Главный принцип",
              "Сначала тепло и вода, потом отделка. Основные потери тепла уходят с испарения, поэтому покрытие и тепловой насос выбирают до мозаики, а водоподготовку считают по объёму и обороту, а не «по мощности фильтра на ценнике». "
              "Мозаика переживёт любые моды, ошибки изоляции и гидравлики не переживёт.")

    s += _sec("0", "Суть: бассейн это четыре замкнутых контура",
              _p("Любой бассейн, химический или природный, держится на четырёх контурах: циркуляция (скиммеры или перелив, насос, фильтр, форсунки), водоподготовка (обеззараживание, pH, прозрачность), "
                 "тепло (нагрев, изоляция, покрытие) и безопасность (покрытие, ограждение, видимость дна). Просадка в любом контуре заметна сразу: мутная вода, счёт за электричество, конденсат в помещении или беда с детьми.")
              + _p("Главное различие философий. Химический бассейн промывает воду медленно и постоянно (полный оборот за 4–6 часов), а хлор, электролиз и УФ поддерживают стерильность. "
                   "Биопул гонит весь объём через зону регенерации и bog-фильтр примерно каждые 40 минут, а прозрачность дают растения и биоплёнка без хлора. Обе схемы рабочие: выбор про эстетику, сервис и готовность ухаживать за экосистемой."))

    s += _sec("1", "Типы бассейнов",
              _tbl(["Тип", "Чаша и отделка", "Вода и сервис", "Особенности"], [
                  ["Химический скиммерный", "Бетон с мозаикой или плёнкой ПВХ, полипропилен, композит", "Хлор или электролиз, УФ, дозаторы pH и ORP; оборот 4–6 ч", "База частного дома; чаша служит десятилетиями"],
                  ["Переливной", "Бетон с мозаикой, переливной лоток и балансировочный бак", "Та же химия, оборот 3–4 ч; зеркало вровень с бортом", "Дороже скиммерного (по практике на пятую часть и больше); общественные и премиум-проекты"],
                  ["Биопул", "Плёнка или полипропилен и зона регенерации 30–50 % площади", "Без хлора: растения, биоплёнка, УФ как опция; оборот 1–2 об/ч", "Дешевле химии в обслуживании, дороже по площади (участок в 1,4–1,5 раза больше зеркала купания)"],
                  ["Каркасный сезонный", "Плёнка на каркасе", "Хлор в таблетках, картриджный фильтр", "Дача на сезон; не зимует в грунте"],
                  ["Купель, спа с противотоком", "Акрил, полипропилен, композит", "Компактная водоподготовка, нагрев до 36–38 °C", "Всесезонно в павильоне или на террасе"],
              ])
              + _note("Тенденции последних лет: насосы с регулируемой скоростью, дозаторы pH и ORP с удалённым контролем, связка электролиз + УФ с низкой дозой хлора, тепловые насосы вместо ТЭНов, "
                      "биопулы в частных садах, автоматические покрытия и датчики падения в воду. Данные по объёмам рынка и конкретным производителям здесь не приводятся: наличие и поддержка в Беларуси меняются."))

    s += _sec("2", "Чаши и материалы",
              _tbl(["Материал чаши", "Срок службы (по практике)", "Плюсы", "Риски", "Когда выбирать"], [
                  ["Бетон с эластичной гидроизоляцией и мозаикой", "Десятилетия при верном монтаже", "Любая форма и глубина, перелив", "Долгий цикл (недели), цена, трещины при осадке без деформационных швов", "Стационарные премиум-проекты, переливные схемы"],
                  ["Полипропилен 5–8 мм", "Десятилетия", "Заводской шов, быстрый монтаж, встроенные закладные", "Габариты транспорта, обсыпка и рёбра жёсткости обязательны, форма ограничена", "Частные скиммерные бассейны под ключ"],
                  ["Композит (стеклопластик)", "Десятилетия", "Одна чаша за день, гладкая поверхность", "Габариты чаши ограничены, осадка грунта даёт трещины гелькоута", "Сезонные и дачные проекты"],
                  ["Плёнка ПВХ около 1,5 мм по любой чаше", "10–15 лет с ремонтом", "Дешевле мозаики, гидроизоляция и отделка за один слой", "Швы варят на месте, боится абразива и льда", "Реновация старых чаш, бюджетные проекты"],
                  ["Биопул: плёнка или полипропилен и зона регенерации", "Как у плёнки или полипропилена", "Без хлора, эстетика природного пруда", "Площадь в 1,4–1,5 раза больше зеркала, уход за растениями", "Эко-сценарий, ландшафтные сады"],
              ])
              + _p("<b>Глубины под задачи.</b> Купание и игры 1,2–1,5 м; дорожка для плавания и противоток 1,4–1,6 м при длине от 8 м; детская зона 0,6–0,8 м с видимой границей дна. "
                   "Прыжки с тумбы возможны только на глубине от 2,4 м, самодельные тумбы на меньшей глубине опасны. Глубже 1,6 м для семейного купания избыточно: больше воды и нагрева.")
              + _p("<b>Закладные до бетона.</b> Скиммеры, форсунки, свет и противоток ставят до бетонирования или обсыпки: алмазное сверление потом ослабляет чашу и портит гидроизоляцию.")
              + _note("Утепление чаши в грунте (плиты XPS по бортам и дну, по практике 50–100 мм) и эластичная гидроизоляция нужны в любой схеме: неутеплённая чаша отдаёт в грунт заметную часть тепла сезона (по практике 10–15 %), а в помещении конденсирует."))

    s += _sec("3", "Вода: циркуляция, фильтрация, обеззараживание, баланс",
              f_circuit()
              + _tbl(["Узел", "Правило подбора", "Ориентир практики"], [
                  ["Насос", "Q = V / t, t = 4–6 ч для скиммерного и 3–4 ч для переливного; напор системы 8–12 м с фильтром", "30 м³: около 5–7,5 м³/ч; регулируемый насос с ночным профилем 40–60 %"],
                  ["Фильтр", "Песок или AFM: нагрузка 30–50 м³/ч на 1 м² площади; промывка при росте давления на 0,3–0,5 бар", "30 м³: диаметр 600–700 мм; картридж только для малых объёмов до 20 м³"],
                  ["Обеззараживание", "Хлор 0,3–0,6 мг/л свободного; электролиз около 8–16 г/ч на 30 м³; УФ 1–2 Вт/м³ в байпасе", "Электролиз с УФ позволяет снизить дозу хлора, режим по паспорту"],
                  ["Баланс", "pH 7,2–7,6, щёлочность 80–120 мг/л, кальций по типу чаши", "Дозаторы pH и ORP держат коридор без участия человека"],
                  ["Биопул", "Без хлора: зона регенерации 30–50 % площади, bog-фильтр, растения около 8 шт/м², УФ по желанию", "Прозрачность: дно видно по всей глубине, ориентир по диску Секки не менее 1,5 м"],
              ])
              + _p("<b>Почему pH первичен.</b> От pH зависит, какая часть хлора находится в активной форме (хлорноватистая кислота): при 7,2 это примерно две трети, при 7,5 около половины, при 8,0 лишь около пятой части. "
                   "Вода при этом пахнет хлором, но почти не дезинфицирует, а ударная доза раздражает кожу и глаза. Поправить pH дешевле любой ударной дозы.")
              + _p("<b>Гидравлика по скоростям.</b> Скорость воды на всасе не более 1,5 м/с, на напоре не более 2 м/с. Для потока 9,6 м³/ч это трубы Ø63 на всасе и Ø50 на напоре, "
                   "для биопула с потоком 100 м³/ч нужны трубы Ø160–200 или несколько линий. Колена по 45°, никаких острых колен у насоса: кавитация и шум.")
              + _note("Вода для купания должна отвечать санитарным требованиям. Они отдельные от требований к декоративному водоёму, их уточняют по санитарным нормам и рекомендациям производителей химии."))

    s += _sec("4", "Тепло и энергия сезона: где живут деньги",
              _ul(["<b>Структура потерь открытой воды.</b> Главная часть уходит с испарения (по оценкам из литературы до 70 %), остальное на излучение и конвекцию, в грунт через чашу и брызги.",
                   "<b>Первичный нагрев.</b> P = V × 1,163 × ΔT / t. Для 30 м³ при подъёме с +15 до +26 °C за сутки это около 16 кВт. Тепловой насос теряет мощность при воздухе ниже +10 °C, поэтому на старт сезона оставляют ТЭН или котёл.",
                   "<b>Потери сезона.</b> Для открытой воды ориентир 0,25 кВт на 1 м² зеркала, с ламельным покрытием около 45 % от этого, с пузырьковой плёнкой около 55 %, в павильоне около 35 %, в помещении около 20 %. Сезон по умолчанию 4 месяца.",
                   "<b>Тепловой насос.</b> Паспортный COP 5–7 даётся при тёплом воздухе. Для мая–сентября в Беларуси реалистичен среднесезонный COP около 4–5 (в калькуляторе 4,5), экономия против ТЭНа в 4–5 раз, а не в 5–7.",
                   "<b>Изоляция чаши и труб.</b> XPS 50–100 мм по бортам и дну, скорлупы на трассах: по практике ещё 10–15 % сезона.",
                   "<b>Павильон.</b> Телескопическое укрытие заметно удлиняет сезон (по практике до 5–6 месяцев вместо 3–4) и почти убирает ветровое испарение."])
              + f_energy()
              + _box("Запоминалка «Три рычага счёта»", "Покрытие, насос, экран. Покрытие снимает испарение, регулируемый насос и тепловой насос экономят электричество, павильон и посадка чаши в ландшафте защищают от ветра и солнца."))

    s += _sec("5", "Монтаж: котлован, закладные, техпомещение, зима",
              _ul(["<b>Котлован</b> с запасом 50–70 см по бортам под обсыпку и изоляцию. При высоком уровне грунтовых вод нужен дренаж по периметру: пустую чашу выдавливает, как септик.",
                   "<b>Закладные до бетона и обсыпки.</b> Скиммеры на 5–10 см ниже зеркала, форсунки напротив по диагонали (мёртвые зоны в углах убирает схема подачи), свет в нишах с герметичными вводами.",
                   "<b>Техпомещение</b> не дальше 10–15 м от чаши (иначе насос не поднимет трассу), с трапом и приямком для промывочных вод, вентиляцией (по практике 3–4 крата), розетками с УЗО 30 мА и местом под дозаторы; шум насоса не за стеной спальни.",
                   "<b>Испытания до отделки.</b> Чаша наливом на 72 часа с отметкой уровня (утечка по практике не более 2 мм в сутки с учётом испарения), трассы давлением в 1,5 раза выше рабочего. Только потом мозаика и обсыпка.",
                   "<b>Зима в Беларуси.</b> Химический бассейн по умолчанию не сливают: уровень ниже скиммера, компенсаторы объёма (демпферы или поплавки), заглушки в закладные, зимний консервант; решение по проекту и паспорту. "
                   "Биопул зимует как пруд: аэратор над ямой и работающий bog. Каркасные бассейны демонтируют по паспорту."])
              + _box("Нормативный контур Беларуси",
                     "Стационарный бассейн это капитальное сооружение, порядок его оформления уточняйте в отделе архитектуры и строительства. Указ Президента № 202 от 13.06.2022 даёт упрощённый порядок для одноквартирных домов "
                     "и нежилых капитальных построек пятого класса сложности, бассейн в его тексте не назван. Отступы от границы: по публикациям об Изменении № 4 к СН 3.01.03-2020 (с 01.12.2026) нормативные расстояния для жилого дома 3 м, "
                     "для хозяйственных построек 2 м, нотариальное согласие соседа их больше не заменяет; отдельная норма для бассейна не подтверждена, поэтому берите ориентир не ближе 3 м и подтверждайте письменно. "
                     "Промывочные и дренажные воды нельзя отводить на соседний участок и на рельеф: их направляют в свой дренаж или канализацию. Безопасность детей ответственность владельца: покрытие, ограждение или датчик падения в воду."))

    s += _sec("6", "Типичные ошибки: 12 способов утопить бюджет",
              _errs([
                  ("Чаша без утепления в грунте", "Тепло уходит в землю, в помещении выпадает конденсат.", "XPS по бортам и дну, скорлупы на трассах."),
                  ("Без покрытия", "Испарение съедает основную часть нагрева, влага рушит помещение.", "Ламели или пузырьковая плёнка; в павильоне автоматика закрытия."),
                  ("Насос «с запасом» без регулировки", "Шум, размыв загрузки фильтра, лишние киловатт-часы.", "Q по обороту, регулируемый насос с сезонными профилями."),
                  ("Диаметры «как у всех»", "Кавитация на всасе, мёртвые зоны у форсунок.", "Скорости не более 1,5 и 2 м/с, диагональная схема подачи."),
                  ("Гидроизоляция без испытаний", "Течь после мозаики: вскрытие чаши.", "Налив на 72 часа с отметкой уровня до отделки, трассы под давлением."),
                  ("Закладные после бетона", "Алмазные керны ослабляют чашу и портят гидроизоляцию.", "Скиммеры, форсунки, свет до бетонирования."),
                  ("Техпомещение без трапа", "Промывка и аварии топят подвал, обслуживание невозможно.", "Трап, приямок, вентиляция, УЗО, доступ к фильтру."),
                  ("Хлор без контроля pH", "При pH 8 активна лишь пятая часть дозы: раздражение и запах при слабой дезинфекции.", "Дозаторы pH и ORP, тест-полоски как резерв."),
                  ("Электролиз без совместимости металлов", "Нержавеющие закладные и лестницы разъедает соль.", "Комплектующие с допуском под солёную воду, контроль солёности."),
                  ("Биопул с хлором или регенерацией 20 %", "Растения гибнут, прозрачность падает, система мертва.", "Без хлора, регенерация 30–50 %, приёмка по прозрачности."),
                  ("Зима сливом «под ноль»", "Грунт выдавливает пустую чашу, трещины по борту.", "Консервация с водой ниже скиммера, демпферы, заглушки, зимняя химия."),
                  ("Без защиты детей", "Открытая вода без покрытия, ограждения и сигнализации.", "Покрытие, ограждение около 1,2 м или датчик падения в воду."),
              ]))

    s += _sec("7", "Приоритеты и чек-лист заказчика",
              _p("Вопросы подрядчику до договора.")
              + _ul(["Расчёт циркуляции: расход, напор, диаметры труб и схема подачи, покажите цифры, а не «стандартный комплект»?",
                     "Чем утеплена чаша и трассы, какие испытания гидроизоляции и трасс входят в сдачу?",
                     "Техпомещение: трап, вентиляция, доступ к фильтру, всё ли на плане?",
                     "Зимний сценарий: консервация или всесезонный режим, что с покрытием и павильоном?",
                     "Безопасность: покрытие, ограждение и сигнализация в спецификации?",
                     "Куда уходят промывочные воды и как оформляется бассейн (порядок, согласования, отступы)?"])
              + _box("Красные флаги", "«Чаша за неделю под ключ» без испытаний наливом; комплект без регулируемого насоса и покрытия «для экономии»; биопул с хлоратором «на всякий случай»; техпомещение без трапа; "
                                      "закладные после бетона; нет зимнего сценария в договоре; промывочные воды «на соседа». Любого пункта достаточно, чтобы остановиться.")
              + _p("Пять тезисов, с которыми можно принимать решение.")
              + _ul(["Бассейн это четыре контура: циркуляция, водоподготовка, тепло, безопасность. Слабейший задаёт впечатление и счёт.",
                     "Тепло стоит дороже чаши: покрытие и тепловой насос дают порядок экономии, считайте по своему сезону и тарифу.",
                     "Химия или биопул это философия: хлор при дисциплине дозирования либо эстетика без реагентов при большей площади.",
                     "Закладные, изоляция и техпомещение решаются до бетона, потом только алмазное сверление и компромиссы.",
                     "Зима часть проекта: не сливать без решения проектировщика, у биопула аэратор и работающий bog; дети: покрытие, ограждение, датчик."])
              + _note("Источники: Указ Президента Республики Беларусь № 202 от 13.06.2022; СН 3.01.03-2020 с Изменением № 4 (по публикациям, текст сверьте); паспорта оборудования. "
                      "Цифры оборота, нагрузки на фильтр, УФ, электролиза, потерь и COP это ориентиры практики, а не нормативы. Оценки энергии для климата Минска, не оферта."))
    return s
